export const FREE_QUIZ = QUIZZES[0];
/* Порядок прохождения. Разборы не равнозначны: один читается ЧЕРЕЗ другой.
   Тип кожи — фундамент, без него остальные ответы нечем интерпретировать;
   чувствительность идёт второй, потому что она про безопасность, а «что мне
   нельзя» надо знать раньше, чем «что мне делать». Дальше состояние сейчас,
   аудит того, чем человек уже пользуется (самая дешёвая правка из всех), и
   только потом стратегия на годы. Морфотип последний: он углубляет картину,
   а углублять нечего, пока картины нет.

   Порядок списка на экране = этот порядок. Сортировать по цене или по
   алфавиту здесь значило бы прятать методологию. */
export const QUIZ_ORDER: Array<{ id: string; why: { ru: string; en: string } }> = [
  { id: 'skintype',    why: { ru: 'Фундамент: остальное читается через тип', en: 'The base: everything else is read through your type' } },
  { id: 'sensitivity', why: { ru: 'Что тебе нельзя — знать раньше, чем что делать', en: 'What you must avoid — before what to do' } },
  { id: 'glow',        why: { ru: 'Состояние кожи сейчас, до любых планов', en: 'Where your skin is right now, before any plan' } },
  { id: 'homecare',    why: { ru: 'Аудит того, что уже делаешь — правится дешевле всего', en: 'Audit what you already do — the cheapest thing to fix' } },
  { id: 'aging',       why: { ru: 'Что стареет первым — план на годы', en: 'What ages first — the multi-year plan' } },
  { id: 'morphotype',  why: { ru: 'Углубляет картину, когда картина уже есть', en: 'Deepens the picture once there is one' } },
];

const ORDER_INDEX = new Map(QUIZ_ORDER.map((o, i) => [o.id, i]));

export const PAID_QUIZZES = QUIZZES.slice(1)
  .slice()
  .sort((a, b) => (ORDER_INDEX.get(a.id) ?? 99) - (ORDER_INDEX.get(b.id) ?? 99));

export const quizWhy = (id: string) => QUIZ_ORDER.find((o) => o.id === id)?.why;
export const quizStep = (id: string) => (ORDER_INDEX.get(id) ?? -1) + 1;
export const findQuiz = (id: string) => QUIZZES.find((q) => q.id === id);

/** Бандл: все шесть платных со скидкой — как на сайте ($49.99 против $89.94) */
/* Цены. Якорь — 1000★ за разбор (≈$20, столько стоит час консультации),
   продажа ровно в полтора раза ниже: 670★ ≈ $13. Ниже опускаться нельзя —
   Telegram удерживает ~30% при выводе, и из 670★ до Анжелики доходит ≈$9.
   Набор — «шесть по цене четырёх»: 4 × 670 = 2680★. Формулировка важнее
   процента: «−33%» надо считать в уме, «шесть по цене четырёх» — нет. */
export const BUNDLE = {
  id: 'bundle',
  title: 'Все шесть разборов',
  stars: 2680,
  fullStars: PAID_QUIZZES.reduce((s, q) => s + q.stars, 0),
  get savePercent() {
    return Math.round((1 - this.stars / this.fullStars) * 100);
  },
};

/** Акция за подписку в инстаграме — промокод, ОТДЕЛЬНО от заданий.
    Скидка за задания живёт в lib/quests.ts и считается своим правилом:
    раньше потолок заданий брался отсюда, и это было совпадением чисел,
    а не общим смыслом. */
export const IG_OFFER = { percent: 30, code: 'IGANZH' };

/** Цена со скидкой. Процент приходит из заданий, а не зашит в формулу */
export const igPrice = (stars: number, percent: number = IG_OFFER.percent) =>
  Math.round((stars * (100 - percent)) / 100 / 10) * 10;
